      <span class="tabs"><button class="btn step" data-page="look"><b>1</b>${H("捏人","Look")}</button><i class="link"></i><button class="btn step" data-page="info"><b>2</b>${H("资料","Profile")}</button><i class="link l2"></i><button class="btn step s3" data-page="job"><b>3</b>${H("营生","Work")}</button></span>
